import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync, mkdtempSync, writeFileSync, mkdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';

const gateScript = resolve('scripts/enforce-quality.sh');

test('the gate is wired into the pre-commit hook', () => {
  assert.match(readFileSync('.githooks/pre-commit', 'utf8'), /enforce-quality\.sh/u);
});

test('the gate runs and reports its own exit status', () => {
  // Exercised rather than read: a gate nobody executes is a gate nobody has.
  const run = () => execFileSync('bash', ['scripts/enforce-quality.sh'], { stdio: 'pipe' });
  assert.doesNotThrow(run);
});

/**
 * Sets up an isolated git repo in a tmp dir so fixture content (conflict
 * markers, debugger statements, ...) never touches this project's own
 * staged diff.
 */
function makeRepo() {
  const dir = mkdtempSync(join(tmpdir(), 'quality-gate-'));
  const git = (...args) => execFileSync('git', args, { cwd: dir, stdio: 'pipe' });
  git('init', '-q');
  git('config', 'user.email', 'test@example.com');
  git('config', 'user.name', 'test');
  git('config', 'commit.gpgsign', 'false');
  return { dir, git };
}

function writeAndStage(repo, relPath, content) {
  const full = join(repo.dir, relPath);
  mkdirSync(resolve(full, '..'), { recursive: true });
  writeFileSync(full, content);
  repo.git('add', relPath);
}

function runGate(repo, env = {}) {
  try {
    const stdout = execFileSync('bash', [gateScript], {
      cwd: repo.dir,
      stdio: 'pipe',
      env: { ...process.env, ...env },
    });
    return { status: 0, stdout: stdout.toString() };
  } catch (error) {
    return { status: error.status, stdout: (error.stdout ?? '').toString() };
  }
}

test('blocks a staged debugger statement', () => {
  const repo = makeRepo();
  writeAndStage(repo, 'src/a.js', 'function f() {\n  debugger;\n}\n');

  const result = runGate(repo);

  assert.equal(result.status, 1);
  assert.match(result.stdout, /BLOCK.*debugger statement/u);
});

test('blocks a staged merge-conflict marker', () => {
  const repo = makeRepo();
  writeAndStage(repo, 'src/a.txt', '<<<<<<< HEAD\nours\n=======\ntheirs\n>>>>>>> branch\n');

  const result = runGate(repo);

  assert.equal(result.status, 1);
  assert.match(result.stdout, /BLOCK.*merge-conflict marker/u);
});

test('warns but does not block on a staged console.log', () => {
  const repo = makeRepo();
  writeAndStage(repo, 'src/a.js', 'console.log("debugging");\n');

  const result = runGate(repo);

  assert.equal(result.status, 0);
  assert.match(result.stdout, /WARN.*console\.log/u);
});

test('warns but does not block on a staged TODO comment', () => {
  const repo = makeRepo();
  writeAndStage(repo, 'src/a.js', '// TODO: revisit this\nconst x = 1;\n');

  const result = runGate(repo);

  assert.equal(result.status, 0);
  assert.match(result.stdout, /WARN.*TODO/u);
});

test('a clean staged diff passes with no findings', () => {
  const repo = makeRepo();
  writeAndStage(repo, 'src/a.js', 'const x = 1;\nmodule.exports = { x };\n');

  const result = runGate(repo);

  assert.equal(result.status, 0);
  assert.doesNotMatch(result.stdout, /BLOCK/u);
  assert.doesNotMatch(result.stdout, /WARN/u);
});

test('QUALITY_GATE_OVERRIDE=1 allows a commit past a blocking finding', () => {
  const repo = makeRepo();
  writeAndStage(repo, 'src/a.js', 'debugger;\n');

  const result = runGate(repo, { QUALITY_GATE_OVERRIDE: '1' });

  assert.equal(result.status, 0);
  assert.match(result.stdout, /BLOCK.*debugger statement/u);
  assert.match(result.stdout, /QUALITY_GATE_OVERRIDE/u);
});

test('only newly added lines are inspected, not pre-existing ones', () => {
  const repo = makeRepo();
  writeAndStage(repo, 'src/a.js', 'debugger;\n');
  repo.git('commit', '-q', '-m', 'pre-existing debugger statement');

  writeAndStage(repo, 'src/b.js', 'const y = 2;\n');

  const result = runGate(repo);

  assert.equal(result.status, 0);
  assert.doesNotMatch(result.stdout, /BLOCK/u);
});

